def load(path):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        print("REFUSED %s: missing (are r107, r107b, r107c and r107d applied?)" % path)
        sys.exit(1)
    raw = open(full, "rb").read()
    crlf = raw.count(b"\r\n")
    if crlf not in (0, raw.count(b"\n")):
        print("REFUSED %s: mixed line ends" % path)
        sys.exit(1)
    return raw, ("\r\n" if crlf else "\n"), raw.decode("utf-8").replace("\r\n", "\n")


def state_of(cur, eds, path):
    done = todo = 0
    for old, new in eds:
        no, nn = cur.count(old), cur.count(new)
        if nn == 1 and no == (1 if old in new else 0):
            done += 1
        elif no == 1 and nn == 0:
            todo += 1
        else:
            print("REFUSED %s: old text found %d times, new text %d times: %r" % (path, no, nn, old[:70]))
            sys.exit(1)
    if done == len(eds):
        return "applied"
    if todo == len(eds):
        return "clean"
    print("REFUSED %s: %d of %d edits applied" % (path, done, len(eds)))
    sys.exit(1)


def text_checks(t):
    """The ties a compiler cannot check, on the texts as they are once applied."""
    layout = t[V + "host_shaders/caustics_layout.h"]
    shader = t[V + "host_shaders/caustics.comp"]
    cpp = t[V + "renderer_vulkan/vk_caustics.cpp"]
    params = t[V + "renderer_vulkan/caustics_params.h"]
    readme = t["README.md"]
    for name in ("SLOT_WORDS 168", "SLOTS 8", "DATA_WORDS 48", "W_PUDDLE_GROUND 31", "W_PUDDLE_WET 32",
                 "W_HEIGHTS 40", "HEIGHT_BINS 128", "HEIGHT_STEP 0.04", "HEIGHT_RANGE 5.12", "PUDDLE_GLOSS 0.8",
                 "PUDDLE_UP 0.9", "PUDDLE_SPEED 0.25", "PUDDLE_CONTRAST 0.5", "WATER_M 0.04", "WATER_REL 0.002",
                 "FLAG_PUDDLE 64u", "FLAG_PUDDLE_PLANE 128u"):
        if layout.count("#define CAUSTICS_" + name + chr(10)) != 1:
            raise SystemExit("text check: caustics_layout.h lacks %r" % name)
    for want in ("PuddleMinShare = 1e-4f, PuddleNear = 0.5f, PuddleKeep = 0.08f, PuddleMaxWet = 0.6f",
                 "PuddleMinPixels = 64, PuddleMinGround = 400, PuddleQuietCalls = 16"):
        if want not in params:
            raise SystemExit("text check: caustics_params.h lacks %r" % want)
    sec = readme[readme.find("### Water caustics (in development)"):readme.find("## Sponsors")]
    # 8 slots x (168 + 48) words x 4 bytes; the constants above in words
    for want in ("6912 bytes", "Water caustics (r107e)", "world y 0.9 or more", "gloss is 0.8 or more",
                 "4 cm steps from 5.12 m below the camera", "read 7 dispatches late", "at least 64 pixels",
                 "a ten-thousandth", "within 8 cm", "at least 400", "at most 0.6", "after 16 such calls",
                 "0.25 of the speed", "1 + 0.5 x (pattern - 1)", "Lamps also over puddles"):
        if want not in sec:
            raise SystemExit("text check: README section lacks %r" % want)
    for gone in ("2560 bytes", "no puddles (nothing found yet"):
        if gone in sec:
            raise SystemExit("text check: README section still says %r" % gone)
    for want in ("bool PuddleAt(ivec2 q)", "CAUSTICS_W_HEIGHTS + bin", "CAUSTICS_W_PUDDLE_GROUND",
                 "CAUSTICS_W_PUDDLE_WET", "Pattern(X.xz, CAUSTICS_PUDDLE_SPEED)", "Pattern(Qw.xz, 1.0)",
                 "i += CAUSTICS_GROUP * CAUSTICS_GROUP"):
        if want not in shader:
            raise SystemExit("text check: the shader lacks %r" % want)
    if shader.count("i < CAUSTICS_SLOT_WORDS; i += CAUSTICS_GROUP * CAUSTICS_GROUP") != 2:
        raise SystemExit("text check: the shader does not clear and add every word in turns")
    if shader.count("layout(binding = ") != 7:
        raise SystemExit("text check: the shader does not have 7 bindings")
    for want in ('"Water caustics (r107e): puddles:', "BC::EstimatePuddle(words + CAUSTICS_W_HEIGHTS",
                 "BC::PuddlesNotFloor(ground, wet)", "calls_since_mirror > BC::PuddleQuietCalls"):
        if want not in cpp:
            raise SystemExit("text check: vk_caustics.cpp lacks %r" % want)


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd not in ("check", "apply", "revert"):
        print("use: check | apply | revert")
        sys.exit(2)
    if not os.path.isdir(os.path.join(ROOT, "engine/gpu")):
        print("%s is not a source tree root (set R107E_ROOT)" % ROOT)
        sys.exit(1)
    plan = []
    for path, eds in EDITS.items():
        raw, eol, cur = load(path)
        plan.append((path, eds, raw, eol, cur, state_of(cur, eds, path)))
    states = {p[5] for p in plan}
    if len(states) != 1:
        print("REFUSED mixed state: " + ", ".join("%s %s" % (p[0], p[5]) for p in plan))
        sys.exit(1)
    state = states.pop()

    def applied_texts():
        out = {}
        for path, eds, raw, eol, cur, _ in plan:
            for old, new in eds:
                cur = cur.replace(old, new, 1)
            if state_of(cur, eds, path) != "applied":
                print("REFUSED %s: the result does not read as applied" % path)
                sys.exit(1)
            out[path] = cur
        return out

    if cmd == "check":
        if state == "applied":
            text_checks({p[0]: p[4] for p in plan})
            print("applied (text checks pass)")
        else:
            text_checks(applied_texts())
            print("not applied; would apply (%d files, %d edits; text checks on the result pass)"
                  % (len(plan), sum(len(p[1]) for p in plan)))
        return
    if cmd == "apply":
        if state == "applied":
            print("already applied")
            return
        texts = applied_texts()
        text_checks(texts)
        os.makedirs(BACKUP, exist_ok=True)
        for path, eds, raw, eol, cur, _ in plan:
            open(os.path.join(BACKUP, path.replace("/", "__")), "wb").write(raw)
        out = {p[0]: texts[p[0]].replace("\n", p[3]).encode("utf-8") for p in plan}
    else:
        if state != "applied":
            print("nothing to revert")
            return
        out = {}
        for path, eds, raw, eol, cur, _ in plan:
            for old, new in reversed(eds):
                cur = cur.replace(new, old, 1)
            if state_of(cur, eds, path) != "clean":
                print("REFUSED %s: the revert does not read as clean; nothing written" % path)
                sys.exit(1)
            out[path] = cur.replace("\n", eol).encode("utf-8")
    written = []
    try:
        for path, eds, raw, eol, cur, _ in plan:
            full = os.path.join(ROOT, path)
            tmp = full + ".r107etmp"
            open(tmp, "wb").write(out[path])
            os.replace(tmp, full)
            written.append((full, raw))
    except OSError as err:
        for full, raw in reversed(written):
            open(full, "wb").write(raw)
        print("REFUSED: write failed (%s); everything written was put back" % err)
        sys.exit(1)
    print("applied" if cmd == "apply" else "reverted")


main()
